/* =====================================================================================
   DM-H1  |  History Checks - Change Creates a New Satellite Row  (MAXIMUS)
   A record changed in the SF Mirror source creates a new satellite row. Pass criterion: new sat row on change.

   Check ID: DM-H1
   Category: History checks
   Sign-off criterion: Change creates a new satellite row
   Method: (a) HASHDIFF integrity on every row; (b) before / after CDC capture of
       sampled keys around a dbt load
   Evidence required: Before/after CDC test evidence
   Pass criteria / tolerance: New sat row on change
   Owner: LUMIQ
   Vault location: BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL
   Maximus RAW: BAGIC_PROD_MIRROR_DB.MAXI_RAW
   Opus RAW (test): BAGIC_PREPROD_CURATED_DB.UTILS (prod:
       BAGIC_PROD_MIRROR_DB.OPUS_GG_DWHSTAGE)
   Scope: Every standard + augmented satellite of the project; rows scoped by the
       project's RECORD_SOURCE prefix.
   Snapshot schema (b): BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION -- tables
       DM_H_CDC_SNAPSHOT / DM_H_RELOAD_SNAPSHOT (transient).
   Project in this file: MAXIMUS

   GENERATED by validation/tools/gen_dm_k.py from the current dbt models -- edit the generator,
   not this file. The queries are IDENTICAL to those in the matching .docx.

   Revision notes:
   - Generated 2026-10-13 from the current maximus_partner_dv_dbt models by
     validation/tools/gen_dm_h.py (satellite lineage from gen_dm_a.py).
   - This file: MAXIMUS only (98 satellites, 91 with mapped payload; standard +
     augmented). The other project is in the sibling file.
   - Static queries (a) run on the data already loaded; the (b) procedures need a dbt
     load between a BEFORE and an AFTER capture and write to the snapshot schema.
   - Sections marked NA load only hard-coded NULL padding or a disabled placeholder.
   ===================================================================================== */


----------------------------------------------------------------------------------------
-- 1. SETUP — CDC test set-up (run once)   [Procedure]
-- Creates the snapshot tables used by DM-H1 (b), DM-H2 (b) and DM-H3 (b). Needs CREATE
-- SCHEMA / TABLE rights on the scratch schema; change VALIDATION_SCHEMA in gen_dm_h.py
-- to use another one.
----------------------------------------------------------------------------------------
create schema if not exists BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION;

create transient table if not exists BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (
    run_id varchar, phase varchar, project varchar, satellite varchar, record_source varchar,
    hkey binary(16), cdk varchar, sat_rows number, sat_max_ldts timestamp_ntz, raw_hash varchar,
    captured_at timestamp_ltz
);

create transient table if not exists BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_RELOAD_SNAPSHOT (
    run_id varchar, phase varchar, project varchar, satellite varchar, row_count number,
    captured_at timestamp_ltz
);



----------------------------------------------------------------------------------------
-- 2. MAXIMUS — CDC before / after test procedure   [Procedure]
-- MAXIMUS RAW is the production mirror -- do NOT modify it. Let one normal load cycle
-- land source changes between BEFORE and AFTER; a satellite whose sample saw no change
-- reports NOT TESTED.
----------------------------------------------------------------------------------------
-- Step 1 (BEFORE): set the run id once and capture every satellite
set DM_H_RUN = 'CDC_MAXIMUS_' || to_char(current_timestamp(), 'YYYYMMDD_HH24MI');
set DM_H_PHASE = 'BEFORE';
-- now run every "(b) CDC capture" statement of this file

-- Step 2: source changes land (natural only), then run the dbt load:
--   dbt run --select <this project's satellites>

-- Step 3 (AFTER): same run id, capture again
set DM_H_PHASE = 'AFTER';
-- run every "(b) CDC capture" statement of this file again

-- Step 4: run the "CDC result" section at the end of DM-H1 (changed keys) and DM-H2 (unchanged keys)



----------------------------------------------------------------------------------------
-- 3. MAXIMUS — SAT_CHANNEL_DEFINITION   [Implemented]
-- HASHDIFF column HASHDIFF_CHANNEL_DEFINITION. Recomputed exactly as automate_dv 0.11.5
-- / sat_multi_source computes it, from the payload stored on the same row. A match
-- proves every payload change changes the HASHDIFF, which is what drives a new row.
-- standard satellite, automate_dv.sat; PK DISTRIBUTION_CHANNEL_HKEY; 1 RECORD_SOURCE
-- group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_CHANNEL_DEFINITION' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_CHANNEL_DEFINITION is null) as null_hashdiff,
       count_if(HASHDIFF_CHANNEL_DEFINITION <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(SUBCHANNELCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUBCHANNELEFFECTIVEDATE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_CHANNEL_DEFINITION <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(SUBCHANNELCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUBCHANNELEFFECTIVEDATE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(DISTRIBUTION_CHANNEL_HKEY, 'HEX'), null)) within group (order by DISTRIBUTION_CHANNEL_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct DISTRIBUTION_CHANNEL_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CHANNEL_DEFINITION' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_DISTRIBUTION_CHANNEL|' || ((nullif(trim(to_varchar("AGENT_CHANNEL")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("SUB_CHANNEL")), ''))) as SUBCHANNELCODE,
               to_varchar((nullif(trim(to_varchar("SUB_CHANNEL_EFFECTIVE_DATE")), ''))) as SUBCHANNELEFFECTIVEDATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select DISTRIBUTION_CHANNEL_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CHANNEL_DEFINITION
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and DISTRIBUTION_CHANNEL_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.SUBCHANNELCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SUBCHANNELEFFECTIVEDATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CHANNEL_DEFINITION', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



