     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COMMON_ADDRESS' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_party_addr_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (case when coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("LAND_MARK")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("AREA")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("POST_OFFICE")), ''))))), upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), '')))))) is null then null else md5(concat_ws('|', coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("LAND_MARK")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("AREA")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("POST_OFFICE")), ''))))), ''), coalesce(upper(trim(to_varchar(((nullif(trim(to_varchar("CITY")), '')))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("STATE")), ''))))), ''), coalesce(upper(trim(to_varchar((nullif(trim(to_varchar("PINCODE")), ''))))), ''))) end) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("CITY")), ''))) as CITY,
               to_varchar((nullif(trim(to_varchar("LAND_MARK")), ''))) as LANDMARK,
               to_varchar((nullif(trim(to_varchar("AREA")), ''))) as LOCALITY,
               to_varchar((nullif(trim(to_varchar("PINCODE")), ''))) as POSTALCODE,
               to_varchar((nullif(trim(to_varchar("POST_OFFICE")), ''))) as POSTOFFICENAME,
               to_varchar((nullif(trim(to_varchar("STATE")), ''))) as STATENAME
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_ADDRESS_ADDRESS_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select LOCATION_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
