      from e3 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_COMMON_ADDRESS', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
