-- 8. MAXIMUS — SAT_COMMON_CONSENT   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_COMMON_CONSENT' as satellite, 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(CONSENTGIVENINDICATOR AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(CONSENTGIVENINDICATOR AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_CONSENT
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

