-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_LNK_PARTY_ROLE_CORE' as satellite, '4 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ROLECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLEENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLESTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLETYPE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ROLECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLEENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLESTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ROLETYPE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_PARTY_ROLE_CORE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_msdp_pv__lnk_party_role_core#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("STAKE_CODE")), ''))) as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("STAKE_CODE")), ''))) as ROLECODE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("STAKE_CODE")), '')))), '') is not null
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2 order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, coalesce(to_varchar(ROLECODE), '^^') || '|' || coalesce(to_varchar(ROLESEQUENCE), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') || '|' || coalesce(e.cdk_2, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLECODE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_LNK_PARTY_ROLE_CORE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_PARTY_ROLE_CORE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('DFADVOCATE#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('DFADVOCATE#1') as ROLECODE,
               cast(null as varchar) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((cast(null as varchar)))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('HCADVOCATE#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('HCADVOCATE#1') as ROLECODE,
               cast(null as varchar) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((cast(null as varchar)))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#3
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('LAWYER#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('LAWYER#1') as ROLECODE,
               to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGLAWYER")), ''))) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGLAWYER")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#4
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('RETAINER#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('RETAINER#1') as ROLECODE,
               to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGRETAINER")), ''))) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGRETAINER")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#5
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('STADVOCATE#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('STADVOCATE#1') as ROLECODE,
               cast(null as varchar) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((cast(null as varchar)))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#6
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('TRADVOCATE#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('TRADVOCATE#1') as ROLECODE,
               to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGTRADVOCATE")), ''))) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DATE_OF_JOININGTRADVOCATE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#7
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('{COALESCE(PARTY_FUNCTION,DEFAULT_ROLE)}#1') as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar('{COALESCE(PARTY_FUNCTION,DEFAULT_ROLE)}#1') as ROLECODE,
               to_varchar((nullif(trim(to_varchar("DATE_OF_START")), ''))) as ROLESTARTDATE,
               to_varchar((nullif(trim(to_varchar("INTERMEDIARY_TYPE")), ''))) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DATE_OF_START")), '')))), '') is not null or nullif(trim(to_varchar((cast(null as varchar)))), '') is not null or nullif(trim(to_varchar((nullif(trim(to_varchar("INTERMEDIARY_TYPE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#8
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("DEFAULT_ROLE")), ''))) as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("DEFAULT_ROLE")), ''))) as ROLECODE,
               cast(null as varchar) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DEFAULT_ROLE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__lnk_party_role_core#9
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("PARTY_FUNCTION")), ''))) as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("PARTY_FUNCTION")), ''))) as ROLECODE,
               cast(null as varchar) as ROLESTARTDATE,
               cast(null as varchar) as ROLETYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("PARTY_FUNCTION")), '')))), '') is not null
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2 order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, coalesce(to_varchar(ROLECODE), '^^') || '|' || coalesce(to_varchar(ROLESEQUENCE), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') || '|' || coalesce(e.cdk_2, '^^') as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLESTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLETYPE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_LNK_PARTY_ROLE_CORE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s3 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_PARTY_ROLE_CORE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION'
),
e3 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_rel__lnk_party_role_core#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("STAKE_NAME")), ''))) as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("STAKE_NAME")), ''))) as ROLECODE,
               to_varchar((nullif(trim(to_varchar("START_DATE")), ''))) as ROLESTARTDATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION
         where nullif(trim(to_varchar((nullif(trim(to_varchar("STAKE_NAME")), '')))), '') is not null or nullif(trim(to_varchar((nullif(trim(to_varchar("START_DATE")), '')))), '') is not null
      )
     where hkey in (select hkey from s3) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2 order by ldts desc) = 1
),
n3 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, coalesce(to_varchar(ROLECODE), '^^') || '|' || coalesce(to_varchar(ROLESEQUENCE), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION' and PARTY_HKEY in (select hkey from s3)
     group by 1, 2
),
x3 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') || '|' || coalesce(e.cdk_2, '^^') as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ROLESTARTDATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e3 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_LNK_PARTY_ROLE_CORE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_RELATION',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n3 n full outer join x3 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s4 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_PARTY_ROLE_CORE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_PARTY_ROLE_CORE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY'
),
e4 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_relparty__lnk_party_role_core#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("FOREIGN_KEY")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("STAKE_CODE")), ''))) as cdk_1,
               to_varchar('1') as cdk_2,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("STAKE_CODE")), ''))) as ROLECODE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_RELATED_PARTY
         where nullif(trim(to_varchar((nullif(trim(to_varchar("STAKE_CODE")), '')))), '') is not null
      )
     where hkey in (select hkey from s4) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2 order by ldts desc) = 1
