       count_if(HASHDIFF_PARTY_ORG_DIRECTORS is null) as null_hashdiff,
       count_if(HASHDIFF_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CESSATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONROLE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CESSATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONROLE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORG_DIRECTORS
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORG_DIRECTORS where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_ORG_DIRECTORS' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#1
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('AUTHORISED_SIGNATORY') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("AUTHORIZED_SIGNATURE")), ''))) as DIRECTORNAME,
               to_varchar('AUTHORISED_SIGNATORY') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("AUTHORIZED_SIGNATURE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#2
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('EMPLOYEE') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_EMPLOYEE")), ''))) as DIRECTORNAME,
               to_varchar('EMPLOYEE') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("NAME_OF_THE_EMPLOYEE")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#3
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('HEAD_FRAUD_PREVENTION_LOSS_MITIGATION') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_HEAD_FRAUD_PREVENTION_AND_LOSS_MITIGATION")), ''))) as DIRECTORNAME,
               to_varchar('HEAD_FRAUD_PREVENTION_LOSS_MITIGATION') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("NAME_OF_THE_HEAD_FRAUD_PREVENTION_AND_LOSS_MITIGATION")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#4
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('INVESTIGATION_OFFICER') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_INVESTIGATION_OFFICER")), ''))) as DIRECTORNAME,
               to_varchar('INVESTIGATION_OFFICER') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("NAME_OF_THE_INVESTIGATION_OFFICER")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#5
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('MARKETING_HEAD') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("MARKETING_HEAD_NAME")), ''))) as DIRECTORNAME,
               to_varchar('MARKETING_HEAD') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("MARKETING_HEAD_NAME")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#6
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('MEDICAL_DIRECTOR') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("MEDICAL_DIRECTOR_NAME")), ''))) as DIRECTORNAME,
               to_varchar('MEDICAL_DIRECTOR') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("MEDICAL_DIRECTOR_NAME")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#7
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('MEDICAL_SUPERINTENDENT') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("MEDICAL_SUPERINTENDENT_NAME")), ''))) as DIRECTORNAME,
               to_varchar('MEDICAL_SUPERINTENDENT') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("MEDICAL_SUPERINTENDENT_NAME")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#8
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar('OWNER') as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               cast(null as varchar) as CESSATIONDATE,
               to_varchar((nullif(trim(to_varchar("OWNERS_FULL_NAME")), ''))) as DIRECTORNAME,
               to_varchar('OWNER') as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("OWNERS_FULL_NAME")), '')))), '') is not null
        union all
        -- via unpivot_mp__pd_prop_sp_pv__party_org_directors#9
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), '')))) AS VARCHAR))), '')) as hkey,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_PRINCIPAL")), ''))) as cdk_1,
               (("REC_REFRESH_AT"::timestamp_ntz)) as ldts,
               to_varchar((nullif(trim(to_varchar("DATE_OF_ACCEPTANCE_OF_RESIGNATION")), ''))) as CESSATIONDATE,
               cast(null as varchar) as DIRECTORNAME,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_PRINCIPAL")), ''))) as PERSONROLE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
         where nullif(trim(to_varchar((nullif(trim(to_varchar("DATE_OF_ACCEPTANCE_OF_RESIGNATION")), '')))), '') is not null or nullif(trim(to_varchar((nullif(trim(to_varchar("TYPE_OF_PRINCIPAL")), '')))), '') is not null
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1 order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, coalesce(to_varchar(PERSONROLE), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_ORG_DIRECTORS
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CESSATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DIRECTORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PERSONROLE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_ORG_DIRECTORS', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 43. MAXIMUS — SAT_PARTY_PAYOUT_PROFILE   [Implemented]
-- HASHDIFF column HASHDIFF_PARTY_PAYOUT_PROFILE. Recomputed exactly as automate_dv
-- 0.11.5 / sat_multi_source computes it, from the payload stored on the same row. A
-- match proves every payload change changes the HASHDIFF, which is what drives a new
-- row. standard satellite, sat_multi_source; PK PARTY_HKEY; 2 RECORD_SOURCE group(s):
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_PARTY_PAYOUT_PROFILE' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_PARTY_PAYOUT_PROFILE is null) as null_hashdiff,
       count_if(HASHDIFF_PARTY_PAYOUT_PROFILE <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(GSTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PAYOUTHOLDREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TDSAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TDSRATE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_PARTY_PAYOUT_PROFILE <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(GSTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PAYOUTHOLDREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TDSAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TDSRATE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_PAYOUT_PROFILE
 where (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_PAYOUT_PROFILE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_PAYOUT_PROFILE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_msdp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((try_to_number(to_varchar("TDS_RATE")))) as TDSRATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_PAYOUT_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.TDSRATE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_PAYOUT_PROFILE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_PAYOUT_PROFILE where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_PAYOUT_PROFILE' and record_source = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("GST_PAYMENT_FLAG")), ''))) as GSTAPPLICABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("HOLD_PAYMENT_INFO")), ''))) as PAYOUTHOLDREASON
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_PAYOUT_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and PARTY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.GSTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PAYOUTHOLDREASON AS VARCHAR))), ''), '^^')))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_PARTY_PAYOUT_PROFILE', 'MAXIMUS_BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;



