               to_varchar(coalesce((nullif(trim(to_varchar("CD_OR_PHOTO_CHARGES")), '')), (nullif(trim(to_varchar("LABOR_OT")), '')), (cast(null as number)), (nullif(trim(to_varchar("NEURO_ICU_CHARGES")), '')), (cast(null as number)), (try_to_number(to_varchar("PER_VISIT_CHARGES_OUTSIDE_CITY_LIMIT"))), (try_to_number(to_varchar("PER_VISIT_CHARGES_WITHIN_CITY_LIMIT"))), (nullif(trim(to_varchar("PRIVATE")), '')), (nullif(trim(to_varchar("SEMI_PRIVATE_ROOM_AC")), '')), (nullif(trim(to_varchar("SEMI_PRIVATE_ROOM_NON_AC")), '')), (nullif(trim(to_varchar("SINGLEPRIVATE_ROOM_AC")), '')), (nullif(trim(to_varchar("SINGLEPRIVATE_ROOM_NON_AC")), '')), (nullif(trim(to_varchar("RATE_PER_KM")), '')), (nullif(trim(to_varchar("SERVICE_CHARGE")), '')), (nullif(trim(to_varchar("SINGLE_DELUXE_ROOM")), '')), (try_to_number(to_varchar("SPECIAL_RATE"))), (nullif(trim(to_varchar("SPECIAL_TARIFF")), '')), (nullif(trim(to_varchar("SUITE")), '')), (nullif(trim(to_varchar("TRIPLE_SHARING_AC")), '')), (nullif(trim(to_varchar("TRIPLE_SHARING_NON_AC")), '')))) as TARIFFRATE,
