LL(NULLIF(UPPER(TRIM(CAST(MANAGERCONFIDENTIALREPORT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MANAGERRECOMMENDATIONONVENDOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUREVISIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUVALIDITYENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUVALIDITYSTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NABHACCREDITATIONLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALTIEUPINFORMATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEARESTSERVICINGBRANCHREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NETWORKSTATUSREMARK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NONDISCLOSUREAGREEMENTSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NORMALOFFER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OFFICEFIREINSURANCEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OFFICEMANAGERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ONLINEPROVIDERREFERENCENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATINGHOURSDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATINGLOCATIONRESTRICTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONBASETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONPLACE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONPLACEFORINSURERWORK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ORIGINCOMP AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ORIGINCONT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHERSERVICESDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PANELDOCTORDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTNERDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PPNTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREVIOUSPROVIDERREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRIORITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROFESSIONALINDEMNITYCOVERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROVIDERPROFILEDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REACTIVATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REACTIVATIONREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICEENGAGEMENTSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICELOCATORPROVIDERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICEREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SINGLESPECIALITYINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SPECIALISEDREPAIRERMAKE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERDETAILDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERLOCATIONDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TEACHINGINSTITUTIONINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATOREMAILADDRESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATORMOBILENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPADESKOPERATINGHOURSSUNDAY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPADESKOPERATINGHOURSWEEKDAY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(USEDCARDEALERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VEHICLEMAKESHANDLED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VENDOREVALUATIONOUTCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VENDOREVALUATIONTEMPLATEREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VISITINGCONSULTANTCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VISITINGSURGEONCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(WORKSHOPCATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(WORKSHOPCLASS AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ACTIVATIONDEACTIVATIONREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDITIONALDETAILSREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ASSESSMENTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(AUTHORISINGMANUFACTURERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BLACKLISTREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CONEXPERTISE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CONTACTPERSONDESIGNATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CONTACTPERSONNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COVEREDAREA AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DEALERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DEALERPROGRAMMETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DEALERTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DELISTINGREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DOCTORTOBEDRATIO AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DOCTORTOPATIENTRATIO AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EMPANELLEDCOMPANIESCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EMPANELLEDINSURERCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EMPANELMENTREQUESTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EMPLOYEEPAINSURANCEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EVALUATINGASSESSORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ICUDOCTORCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ICUDOCTORTOBEDRATIO AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ICUNURSETOBEDRATIO AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INSURERVISITCONDUCTEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LKQPARTSACCEPTEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MANAGERCONFIDENTIALREPORT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MANAGERRECOMMENDATIONONVENDOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUREVISIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUVALIDITYENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOUVALIDITYSTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NABHACCREDITATIONLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALTIEUPINFORMATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEARESTSERVICINGBRANCHREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NETWORKSTATUSREMARK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NONDISCLOSUREAGREEMENTSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NORMALOFFER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OFFICEFIREINSURANCEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OFFICEMANAGERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ONLINEPROVIDERREFERENCENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATINGHOURSDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATINGLOCATIONRESTRICTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONBASETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONPLACE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OPERATIONPLACEFORINSURERWORK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ORIGINCOMP AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ORIGINCONT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHERSERVICESDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PANELDOCTORDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTNERDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PPNTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREVIOUSPROVIDERREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRIORITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROFESSIONALINDEMNITYCOVERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROVIDERPROFILEDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REACTIVATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REACTIVATIONREASON AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICEENGAGEMENTSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICELOCATORPROVIDERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SERVICEREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SINGLESPECIALITYINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SPECIALISEDREPAIRERMAKE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERDETAILDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERLOCATIONDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUPPLIERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TEACHINGINSTITUTIONINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATOREMAILADDRESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATORMOBILENUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPACOORDINATORNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPADESKOPERATINGHOURSSUNDAY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TPADESKOPERATINGHOURSWEEKDAY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(USEDCARDEALERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VEHICLEMAKESHANDLED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VENDOREVALUATIONOUTCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VENDOREVALUATIONTEMPLATEREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VISITINGCONSULTANTCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(VISITINGSURGEONCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(WORKSHOPCATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(WORKSHOPCLASS AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_PROVIDER
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_PROVIDER where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_LNK_ROLE_PROVIDER' and record_source = 'MAXIMUS_pd_prop_sp_pv'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("REASON_FOR_ACTIVATIONDEACTIVATION")), ''))) as ACTIVATIONDEACTIVATIONREASON,
               to_varchar((nullif(trim(to_varchar("OTHER_DETAILS")), ''))) as ADDITIONALDETAILSREMARKS,
               to_varchar((nullif(trim(to_varchar("DATE_OF_ASSESSMENT")), ''))) as ASSESSMENTDATE,
               to_varchar((nullif(trim(to_varchar("AUTHORIZED_BY_MFG_CO_NAME")), ''))) as AUTHORISINGMANUFACTURERNAME,
               to_varchar((nullif(trim(to_varchar("REASON_FOR_BLACKLISTING")), ''))) as BLACKLISTREASON,
               to_varchar((nullif(trim(to_varchar("CONTRACTORS_EXPERTISE_IN_STRUCTUREPROJECT")), ''))) as CONEXPERTISE,
               to_varchar((nullif(trim(to_varchar("DESIGNATION_OF_THE_PERSON")), ''))) as CONTACTPERSONDESIGNATION,
               to_varchar((nullif(trim(to_varchar("CONTACT_PERSON_NAME")), ''))) as CONTACTPERSONNAME,
               to_varchar((nullif(trim(to_varchar("COVERED_AREA_IN_KMS")), ''))) as COVEREDAREA,
               to_varchar((nullif(trim(to_varchar("DEALER_CODE")), ''))) as DEALERCODE,
               to_varchar((nullif(trim(to_varchar("REASON_FOR_DELISTING")), ''))) as DELISTINGREASON,
               to_varchar((nullif(trim(to_varchar("DOCTOR_BED_RATIO_NO_OF_MEDICAL_PRACTITIONERS_WITH_MBBS_QUALIFICATIONS_AS_PROPORTION_OF_BEDS")), ''))) as DOCTORTOBEDRATIO,
               to_varchar((nullif(trim(to_varchar("SPAN_OF_CONTROL_DOCTOR_TO_PATIENT")), ''))) as DOCTORTOPATIENTRATIO,
               to_varchar((nullif(trim(to_varchar("NO_OF_COMPANIES_EMPANELLED_WITH")), ''))) as EMPANELLEDCOMPANIESCOUNT,
               to_varchar((nullif(trim(to_varchar("NO_OF_INSURANCE_COMPANIES_EMPANELLED_WITH")), ''))) as EMPANELLEDINSURERCOUNT,
               to_varchar((nullif(trim(to_varchar("EMPANELMENT_REQUEST_DATE")), ''))) as EMPANELMENTREQUESTDATE,
               to_varchar((nullif(trim(to_varchar("DOES_THE_SERVICE_PROVIDER_HAVE_PA_INSURANCE_FOR_EMPLOYEES")), ''))) as EMPLOYEEPAINSURANCEINDICATOR,
               to_varchar((nullif(trim(to_varchar("NAME_OF_ASSESSOR")), ''))) as EVALUATINGASSESSORNAME,
               to_varchar((nullif(trim(to_varchar("NO_OF_DOCTORS_EXCLUSIVELY_AVAILABLE_FOR_ICU")), ''))) as ICUDOCTORCOUNT,
               to_varchar((nullif(trim(to_varchar("DOCTORPATIENTBED_RATIO_IN_ICU_NO_OF_MEDICAL_PRACTITIONERS_EXCLUSIVELY_FOR_ICU_AS_PROPORTION_OF_BEDS_IN_ICU")), ''))) as ICUDOCTORTOBEDRATIO,
               to_varchar((nullif(trim(to_varchar("NURSEPATIENT_BED_RATIO_IN_ICU_NUMBER_OF_QUALIFIED_NURSES_EXCLUSIVELY_FOR_ICU_AS_PROPORTION_OF_BEDS_IN_ICU")), ''))) as ICUNURSETOBEDRATIO,
               to_varchar((nullif(trim(to_varchar("VISITED_BY_BAGIC_PERSON")), ''))) as INSURERVISITCONDUCTEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("MANAGER_CONFIDENTIAL_REPORT")), ''))) as MANAGERCONFIDENTIALREPORT,
               to_varchar((nullif(trim(to_varchar("MANAGER_RECOMMENDATION_ON_VENDOR")), ''))) as MANAGERRECOMMENDATIONONVENDOR,
               to_varchar((nullif(trim(to_varchar("MOU_DETAILS")), ''))) as MOUDETAIL,
               to_varchar((nullif(trim(to_varchar("DATE_OF_MOU_REVISION")), ''))) as MOUREVISIONDATE,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_MOU")), ''))) as MOUTYPE,
               to_varchar((nullif(trim(to_varchar("MOU_VALIDITY_END_DATE")), ''))) as MOUVALIDITYENDDATE,
               to_varchar((nullif(trim(to_varchar("MOU_VALIDITY_START_DATE")), ''))) as MOUVALIDITYSTARTDATE,
               to_varchar((nullif(trim(to_varchar("NABH_ACCREDITATION_LEVEL")), ''))) as NABHACCREDITATIONLEVEL,
               to_varchar((nullif(trim(to_varchar("NATIONAL_TIEUP_INFORMATION")), ''))) as NATIONALTIEUPINFORMATION,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_STATUS_REMARK")), ''))) as NETWORKSTATUSREMARK,
               to_varchar((nullif(trim(to_varchar("NONDISCLOSURE_INITIATED")), ''))) as NONDISCLOSUREAGREEMENTSTATUS,
               to_varchar((nullif(trim(to_varchar("NORMAL_OFFER")), ''))) as NORMALOFFER,
               to_varchar((nullif(trim(to_varchar("DOES_THE_SERVICE_PROVIDER_HAVE_FIRE_INSURANCE_POLICY_FOR_HIS_OFFICE")), ''))) as OFFICEFIREINSURANCEINDICATOR,
               to_varchar((nullif(trim(to_varchar("ONLINE_HOSPITAL_REFERENCE_NUMBER")), ''))) as ONLINEPROVIDERREFERENCENUMBER,
               to_varchar((nullif(trim(to_varchar("OPERATING_HRS")), ''))) as OPERATINGHOURSDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("LOCATION_RESTRICTION")), ''))) as OPERATINGLOCATIONRESTRICTION,
               to_varchar((nullif(trim(to_varchar("OPERATION_FROM_OFFICE_OR_RESIDENCE_OR_OFFICE_CUM_RESIDENCE_TOTAL")), ''))) as OPERATIONBASETYPE,
               to_varchar((nullif(trim(to_varchar("PLACE_OF_OPERATION")), ''))) as OPERATIONPLACE,
               to_varchar((nullif(trim(to_varchar("OPERATION_FROM_OFFICE_OR_RESIDENCE_OR_OFFICE_CUM_RESIDENCE_FOR_BAGIC")), ''))) as OPERATIONPLACEFORINSURERWORK,
               to_varchar((nullif(trim(to_varchar("ORIGIN_OF_THE_COMPANY")), ''))) as ORIGINCOMP,
               to_varchar((nullif(trim(to_varchar("ORIGIN_OF_THE_CONTRACTOR")), ''))) as ORIGINCONT,
               to_varchar((nullif(trim(to_varchar("OTHER_SERVICES")), ''))) as OTHERSERVICESDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("PROVIDER_DOCTOR_DETAILS")), ''))) as PANELDOCTORDETAILS,
               to_varchar((nullif(trim(to_varchar("PARTNER_DETAILS")), ''))) as PARTNERDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("PPN_TYPES")), ''))) as PPNTYPE,
               to_varchar((nullif(trim(to_varchar("PREVIOUS_PROVIDER_REFERENCE")), ''))) as PREVIOUSPROVIDERREFERENCE,
               to_varchar((nullif(trim(to_varchar("PROVIDER_PRIORITY")), ''))) as PRIORITY,
               to_varchar((nullif(trim(to_varchar("MEDICAL_ESTABLISHMENT_INDEMNITY_COVER_PRESENT")), ''))) as PROFESSIONALINDEMNITYCOVERINDICATOR,
               to_varchar((nullif(trim(to_varchar("PROFILE_OF_THE_SERVICE_PROVIDER")), ''))) as PROVIDERPROFILEDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("REACTIVATION_DATE")), ''))) as REACTIVATIONDATE,
