               to_varchar((nullif(trim(to_varchar("TPA_TIMINGS_MON_TO_SAT")), ''))) as TPADESKOPERATINGHOURSWEEKDAY,
               to_varchar((nullif(trim(to_varchar("USED_CAR_DEALER")), ''))) as USEDCARDEALERINDICATOR,
               to_varchar((nullif(trim(to_varchar("VENDOR_EVALUATION")), ''))) as VENDOREVALUATIONOUTCOME,
               to_varchar((nullif(trim(to_varchar("VENDOR_EVALUATION_TEMPLATE")), ''))) as VENDOREVALUATIONTEMPLATEREFERENCE,
               to_varchar((nullif(trim(to_varchar("NO_OF_CONSULTANT_WHO_ARE_NOT_ON_ROLLS_OF_THE_HOSPITAL")), ''))) as VISITINGCONSULTANTCOUNT,
               to_varchar((nullif(trim(to_varchar("NO_OF_SURGEONS_OR_INTERVENTIONISTSNOT_ON_FULL_TIME_ROLL_OF_HOSPITAL")), ''))) as VISITINGSURGEONCOUNT,
               to_varchar((nullif(trim(to_varchar("WORKSHOP_CATEGORY")), ''))) as WORKSHOPCATEGORY,
