-- 62. MAXIMUS — SAT_AUG_LNK_ROLE_SURVEYOR   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. augmented satellite,
-- automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s): MAXIMUS_pd_prop_sp_pv [4
-- col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_LNK_ROLE_SURVEYOR' as satellite, 'MAXIMUS_pd_prop_sp_pv' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(PERFORMANCEEVALUATIONFORMREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERFORMANCEEVALUATIONOUTCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REPORTTIMELINESSRATING AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SURVEYORTYPE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(PERFORMANCEEVALUATIONFORMREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERFORMANCEEVALUATIONOUTCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REPORTTIMELINESSRATING AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SURVEYORTYPE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_SURVEYOR
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_SURVEYOR where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_LNK_ROLE_SURVEYOR' and record_source = 'MAXIMUS_pd_prop_sp_pv'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("SURVEYOR_PERFORMANCE_EVALUATION_FORM")), ''))) as PERFORMANCEEVALUATIONFORMREFERENCE,
               to_varchar((nullif(trim(to_varchar("SURVEYOR_PERFORMANCE_EVALUATION_REPORT")), ''))) as PERFORMANCEEVALUATIONOUTCOME,
               to_varchar((nullif(trim(to_varchar("TIMELY_SUBMISSION_OF_REPORT")), ''))) as REPORTTIMELINESSRATING,
               to_varchar((nullif(trim(to_varchar("TYPE_OF_SURVEYOR")), ''))) as SURVEYORTYPE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_LNK_ROLE_SURVEYOR
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.PERFORMANCEEVALUATIONFORMREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PERFORMANCEEVALUATIONOUTCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REPORTTIMELINESSRATING AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SURVEYORTYPE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_LNK_ROLE_SURVEYOR', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



