-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
