       count_if(HASHDIFF_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(BASICQUALIFICATIONDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BASICQUALIFICATIONROLLNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EDUCATIONINSTITUTENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FATHERORSPOUSENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INCOMEBANDLOWERBOUND AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INCOMEBANDUPPERBOUND AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MARRIAGEANNIVERSARYDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MATRICULATIONQUALIFICATIONDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MONTHLYGROSSINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOTHERSMAIDENNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFDAUGHTERS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFSONS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONLIST AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHEROCCUPATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHERQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONALDETAILSDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTGRADUATEQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROFESSIONALQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONBOARDNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONPASSINGMONTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(UNDERGRADUATEQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(YEAROFPASSINGQUALIFICATION AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(BASICQUALIFICATIONDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BASICQUALIFICATIONROLLNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EDUCATIONINSTITUTENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FATHERORSPOUSENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INCOMEBANDLOWERBOUND AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INCOMEBANDUPPERBOUND AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MARRIAGEANNIVERSARYDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MATRICULATIONQUALIFICATIONDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MONTHLYGROSSINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MOTHERSMAIDENNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFDAUGHTERS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFSONS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONLIST AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHEROCCUPATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OTHERQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PERSONALDETAILSDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTGRADUATEQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PROFESSIONALQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONBOARDNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(QUALIFICATIONPASSINGMONTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(UNDERGRADUATEQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(YEAROFPASSINGQUALIFICATION AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_msdp_pv') or (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS where RECORD_SOURCE = 'MAXIMUS_pd_prop_msdp_pv' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS' and record_source = 'MAXIMUS_pd_prop_msdp_pv'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_msdp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("FOREIGN_KEY")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("FROM_INCOME")), ''))) as INCOMEBANDLOWERBOUND,
               to_varchar((nullif(trim(to_varchar("TO_INCOME")), ''))) as INCOMEBANDUPPERBOUND
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_msdp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.INCOMEBANDLOWERBOUND AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INCOMEBANDUPPERBOUND AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PARTY_INDIVIDUAL_DEMOGRAPHICS', 'MAXIMUS_pd_prop_msdp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

