               to_varchar((nullif(trim(to_varchar("KYC_DETAILS")), ''))) as KYCDETAIL,
               to_varchar((nullif(trim(to_varchar("KYC_RELATED_DETAILS")), ''))) as KYCRELATEDDETAIL,
               to_varchar((nullif(trim(to_varchar("POP_OPTIONAL")), ''))) as OPTIONALPROOFOFPOSSESSIONTYPE,
               to_varchar((nullif(trim(to_varchar("PAN_AADHAAR_LINKED")), ''))) as PANAADHARLINKED,
               to_varchar((nullif(trim(to_varchar("PAN_APPLIED_FOR")), ''))) as PANAPPLIEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("PAN_APPLICATION_NO")), ''))) as PANAPPNO,
               to_varchar((nullif(trim(to_varchar("POP_PRIMARY")), ''))) as PRIMARYPROOFOFPOSSESSIONTYPE,
               to_varchar((nullif(trim(to_varchar("POA_STATUS")), ''))) as PROOFOFADDRESSSTATUS,
               to_varchar((nullif(trim(to_varchar("POI_STATUS")), ''))) as PROOFOFIDENTITYSTATUS,
               to_varchar((nullif(trim(to_varchar("SUBMISSION_OF_REQUIRED_DOCUMENTS")), ''))) as REQUIREDDOCUMENTSSUBMITTEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("SERVICE_TAX_COPY")), ''))) as SERVICETAXCERTIFICATESUBMITTEDINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_KYC
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CKYCDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CKYCNUMBERHELDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.HOSPITALDOCUMENTSAVAILABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.KYCDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.KYCRELATEDDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OPTIONALPROOFOFPOSSESSIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PANAADHARLINKED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PANAPPLIEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PANAPPNO AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PRIMARYPROOFOFPOSSESSIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PROOFOFADDRESSSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PROOFOFIDENTITYSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REQUIREDDOCUMENTSSUBMITTEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SERVICETAXCERTIFICATESUBMITTEDINDICATOR AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PARTY_KYC', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



