     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_PARTY_MARKETING' and record_source = 'MAXIMUS_pd_prop_sp_pv'
),
