               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("ALTERNATE_LOCATION_DETAILS")), ''))) as ALTERNATELOCATIONDETAILS,
               to_varchar((nullif(trim(to_varchar("BUSINESS_DETAILS")), ''))) as BUSINESSDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("SECTOR_SELECTION")), ''))) as BUSINESSSECTORCODE,
               to_varchar((nullif(trim(to_varchar("CLIENT_GEOGRAPHY")), ''))) as CLIENTGEOGRAPHY,
               to_varchar((nullif(trim(to_varchar("ADDRESS_OF_THE_COORDINATING_OFFICE")), ''))) as COORDINATINGOFFICEADDRESS,
               to_varchar((nullif(trim(to_varchar("CREDIT_LIMIT_CIN_NO")), ''))) as CREDITLIMITCINNUMBER,
               to_varchar((nullif(trim(to_varchar("STAFF_STRENGTH_FOR_BAGIC")), ''))) as DEDICATEDSTAFFCOUNTFORINSURER,
               to_varchar((nullif(trim(to_varchar("TEAM_LEADER_FOR_BAGIC")), ''))) as DEDICATEDTEAMLEADERCOUNTFORINSURER,
               to_varchar((nullif(trim(to_varchar("INFRASTRUCTURE_SUBSECTOR")), ''))) as INFRASTRUCTURESUBSECTOR,
               to_varchar((nullif(trim(to_varchar("OTHER_ENTITIES")), ''))) as OTHERRELATEDENTITIES,
               to_varchar((nullif(trim(to_varchar("OWNERSHIP")), ''))) as OWNERSHIPTYPE,
               to_varchar((nullif(trim(to_varchar("IS_THE_ORGANISATION_A_REGISTERED_BUSINESS_TRUST")), ''))) as REGISTEREDBUSINESSTRUSTINDICATOR,
               to_varchar((nullif(trim(to_varchar("ARE_YOU_REGISTERED_COMPANY")), ''))) as REGISTEREDCOMPANYINDICATOR,
               to_varchar((nullif(trim(to_varchar("BUSINESS_COMPANY")), ''))) as REPRESENTEDBUSINESSNAME,
               to_varchar((nullif(trim(to_varchar("TEAM_LEADER_TOTAL")), ''))) as TOTALTEAMLEADERCOUNT,
               to_varchar((nullif(trim(to_varchar("TOTAL_TEAM_STRENGTH")), ''))) as TOTALTEAMSTRENGTH,
               to_varchar((nullif(trim(to_varchar("YEAR_OF_ESTABLISHMENT_OF_CONTRACTORS_FIRM")), ''))) as YEAROFESTABLISHMENT
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORGANISATION_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ALTERNATELOCATIONDETAILS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.BUSINESSDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.BUSINESSSECTORCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLIENTGEOGRAPHY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.COORDINATINGOFFICEADDRESS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CREDITLIMITCINNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DEDICATEDSTAFFCOUNTFORINSURER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DEDICATEDTEAMLEADERCOUNTFORINSURER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INFRASTRUCTURESUBSECTOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OTHERRELATEDENTITIES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OWNERSHIPTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REGISTEREDBUSINESSTRUSTINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REGISTEREDCOMPANYINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REPRESENTEDBUSINESSNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TOTALTEAMLEADERCOUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TOTALTEAMSTRENGTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.YEAROFESTABLISHMENT AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PARTY_ORGANISATION_PROFILE', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



