-- 88. MAXIMUS — SAT_AUG_PARTY_ORG_DIRECTORS   [Implemented]
-- HASHDIFF column HASHDIFF_AUG_PARTY_ORG_DIRECTORS. Recomputed exactly as automate_dv
-- 0.11.5 / sat_multi_source computes it, from the payload stored on the same row. A
-- match proves every payload change changes the HASHDIFF, which is what drives a new
-- row. augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [1 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_ORG_DIRECTORS' as satellite, 'MAXIMUS_pd_prop_sp_pv' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_AUG_PARTY_ORG_DIRECTORS is null) as null_hashdiff,
       count_if(HASHDIFF_AUG_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORANDPARTNERDETAIL AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_AUG_PARTY_ORG_DIRECTORS <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(DIRECTORANDPARTNERDETAIL AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_ORG_DIRECTORS
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
