               to_varchar((nullif(trim(to_varchar("RELATIONSHIP_WITH_HNI")), ''))) as HNIRELATIONSHIPDETAIL,
               to_varchar((nullif(trim(to_varchar("RELATIONSHIP_WITH_PRIVE")), ''))) as PRIVERELATIONSHIPDETAIL,
               to_varchar((nullif(trim(to_varchar("REFERENCE_CODE")), ''))) as REFERENCECODE,
               to_varchar((nullif(trim(to_varchar("REFERENCE")), ''))) as REFERENCENAME,
               to_varchar((nullif(trim(to_varchar("ANY_RELATION_WITH_BAJAJ_GROUP")), ''))) as RELATEDTOINSURERGROUPINDICATOR,
               to_varchar((nullif(trim(to_varchar("NAME_OF_THE_ZONAL_OR_NATIONAL_MANAGER")), ''))) as RELATIONSHIPOWNERMANAGERNAME,
               to_varchar((nullif(trim(to_varchar("TRANSACTS_BUSINESS_WITH_OTHER_BAGIC_OFFICE_ALSO")), ''))) as TRANSACTSWITHOTHEROFFICEINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_RELATIONSHIP_PROFILE
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.EMPLOYEERELATIONSHIPDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EXISTINGCUSTOMERINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GROUPCOMPANYRELATIONSHIPDECLARATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.HNIRELATIONSHIPDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PRIVERELATIONSHIPDETAIL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REFERENCECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REFERENCENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RELATEDTOINSURERGROUPINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RELATIONSHIPOWNERMANAGERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TRANSACTSWITHOTHEROFFICEINDICATOR AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PARTY_RELATIONSHIP_PROFILE', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



