-- 94. MAXIMUS — SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS   [Implemented]
-- HASHDIFF column HASHDIFF_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS. Recomputed exactly as
