-- group(s): MAXIMUS_pd_prop_sp_pv [5 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS' as satellite, 'MAXIMUS_pd_prop_sp_pv' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS is null) as null_hashdiff,
       count_if(HASHDIFF_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGREEDREPORTSUBMISSIONTAT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ALLOCATIONTHRESHOLDLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EVIDENCERETENTIONTHREEYEARSINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OUTSOURCINGJUSTIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TASKALLOCATIONTHRESHOLD AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGREEDREPORTSUBMISSIONTAT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ALLOCATIONTHRESHOLDLEVEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EVIDENCERETENTIONTHREEYEARSINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OUTSOURCINGJUSTIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TASKALLOCATIONTHRESHOLD AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
