               to_varchar((nullif(trim(to_varchar("WHY_THE_INVESTIGATION_TO_BE_OUTSOURCED_TO_THIS_SERVICE_PROVIDER")), ''))) as OUTSOURCINGJUSTIFICATION,
               to_varchar((nullif(trim(to_varchar("TASK_THRESHOLD")), ''))) as TASKALLOCATIONTHRESHOLD,
               to_varchar((nullif(trim(to_varchar("TRAINING_IS_REQUIRED_TO_BE_GIVEN_TO_THE_EMPLOYEES_OF_THE_SERVICE_PROVIDER")), ''))) as TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.AGREEDREPORTSUBMISSIONTAT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EVIDENCERETENTIONTHREEYEARSINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OUTSOURCINGJUSTIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TASKALLOCATIONTHRESHOLD AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TRAININGREQUIREDFORPROVIDEREMPLOYEESINDICATOR AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PARTY_SERVICE_ENGAGEMENT_TERMS', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



