       and satellite = 'SAT_AUG_PROVIDER_QUALITY' and record_source = 'MAXIMUS_pd_prop_sp_pv'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("ERROR_COMMITTED_DURING_ASSESSMENT")), ''))) as ASSESSMENTERRORDESCRIPTION,
               to_varchar((nullif(trim(to_varchar("QUALITY_OF_ASSESSMENT_REPORT")), ''))) as ASSESSMENTREPORTQUALITYSCORE,
               to_varchar((nullif(trim(to_varchar("AVERAGE_ADMISSION_TIME")), ''))) as AVERAGEADMISSIONTIME,
               to_varchar((nullif(trim(to_varchar("AVERAGE_DISCHARGE_TIME")), ''))) as AVERAGEDISCHARGETIME,
               to_varchar((nullif(trim(to_varchar("AVERAGE_LENGTH_OF_STAY_FOR_MEDICAL_CASES")), ''))) as AVERAGELENGTHOFSTAYMEDICALCASES,
               to_varchar((nullif(trim(to_varchar("AVERAGE_LENGTH_OF_STAY_FOR_SURGICAL_CASES")), ''))) as AVERAGELENGTHOFSTAYSURGICALCASES,
               to_varchar((nullif(trim(to_varchar("BED_OCCUPANCY_RATE_IN_HOSPITAL")), ''))) as BEDOCCUPANCYRATE,
               to_varchar((nullif(trim(to_varchar("CERTIFICATION_NO")), ''))) as CERTIFICATIONNUMBER,
               to_varchar((nullif(trim(to_varchar("CERTIFICATION")), ''))) as CERTIFICATIONTYPE,
               to_varchar((nullif(trim(to_varchar("SCORE_OF_CITY")), ''))) as CITYSCORE,
               to_varchar((try_to_number(to_varchar("C_SECTION_RATE")))) as CSECTIONRATE,
               to_varchar((try_to_number(to_varchar("SCORE_OF_DISCOUNT")))) as DISCOUNTSCORE,
               to_varchar((nullif(trim(to_varchar("DISCREPANCY")), ''))) as DISCREPANCYNOTED,
               to_varchar((nullif(trim(to_varchar("RECOMMENDATION")), ''))) as EMPANELMENTRECOMMENDATION,
               to_varchar((nullif(trim(to_varchar("EVALUATION_LOG_INFORMATION")), ''))) as EVALUATIONLOGINFORMATION,
               to_varchar((nullif(trim(to_varchar("FINAL_RATING_AND_RECOMMENDATION")), ''))) as EVALUATIONRECOMMENDATION,
               to_varchar((nullif(trim(to_varchar("EVALUATION_REPORT")), ''))) as EVALUATIONREPORTREFERENCE,
               to_varchar((nullif(trim(to_varchar("ILM_FEEDBACK")), ''))) as ILMREVIEWFEEDBACK,
               to_varchar((nullif(trim(to_varchar("ILM_REMARKS")), ''))) as ILMREVIEWREMARKS,
               to_varchar((nullif(trim(to_varchar("CODING_PROCEDURE_FOLLOWED_BY_MEDICAL_RECORDS_DEPARTMENT")), ''))) as MEDICALRECORDSCODINGPROCEDURE,
               to_varchar((nullif(trim(to_varchar("VOLUME_OF_CASES_FROM_OTHER_INDUSTRY_MONTHLYFOR_BAGIC")), ''))) as MONTHLYCASEVOLUMEOTHERINDUSTRYDEDICATED,
               to_varchar((nullif(trim(to_varchar("VOLUME_OF_CASES_FROM_OTHER_INDUSTRY_MONTHLY_TOTAL")), ''))) as MONTHLYCASEVOLUMEOTHERINDUSTRYTOTAL,
               to_varchar((nullif(trim(to_varchar("VOLUME_OF_CASES_FROM_OTHER_INSURANCE_COMPANY_MONTHLYFOR_BAGIC")), ''))) as MONTHLYCASEVOLUMEOTHERINSURERDEDICATED,
               to_varchar((nullif(trim(to_varchar("VOLUME_OF_CASES_FROM_OTHER_INSURANCE_COMPANY_MONTHLYTOTAL")), ''))) as MONTHLYCASEVOLUMEOTHERINSURERTOTAL,
               to_varchar((nullif(trim(to_varchar("PROACTIVE_APPROACH_IN_DECISION_MAKING")), ''))) as PROACTIVEDECISIONMAKINGSCORE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_GRADE")), ''))) as PROVIDERGRADE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_QUALIFIER")), ''))) as PROVIDERQUALIFIER,
               to_varchar((nullif(trim(to_varchar("QRS_DATE")), ''))) as QRSEVALUATIONDATE,
               to_varchar((nullif(trim(to_varchar("QRS_STATUS")), ''))) as QRSSTATUS,
               to_varchar((nullif(trim(to_varchar("QRS_TYPE")), ''))) as QRSTYPE,
               to_varchar((nullif(trim(to_varchar("QUALITY_CHECK_FOR_BAGIC")), ''))) as QUALITYCHECKSTAFFCOUNTDEDICATED,
               to_varchar((nullif(trim(to_varchar("QUALITY_CHECK_TOTAL")), ''))) as QUALITYCHECKSTAFFCOUNTTOTAL,
               to_varchar((nullif(trim(to_varchar("RC_REGIONAL_COORDINATORS_REMARK")), ''))) as REGIONALCOORDINATORREMARK,
               to_varchar((nullif(trim(to_varchar("MEDICAL_AUDIT_ON_REGULAR_BASIS")), ''))) as REGULARMEDICALAUDITINDICATOR,
               to_varchar((coalesce(nullif(trim(to_varchar("FEED_BACK_FROM_REPAIRER_BEHAVIOR")), ''), nullif(trim(to_varchar("FEED_BACK_FROM_REPAIRER_BEHAVIOUR")), '')))) as REPAIRERCONDUCTFEEDBACK,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_VISITED_BY")), ''))) as SITEVISITCONDUCTEDBY,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_VISITED")), ''))) as SITEVISITCONDUCTEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_VISIT_DATE")), ''))) as SITEVISITDATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_QUALITY
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ASSESSMENTERRORDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ASSESSMENTREPORTQUALITYSCORE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.AVERAGEADMISSIONTIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.AVERAGEDISCHARGETIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.AVERAGELENGTHOFSTAYMEDICALCASES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.AVERAGELENGTHOFSTAYSURGICALCASES AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.BEDOCCUPANCYRATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CERTIFICATIONNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CERTIFICATIONTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CITYSCORE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CSECTIONRATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DISCOUNTSCORE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DISCREPANCYNOTED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EMPANELMENTRECOMMENDATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EVALUATIONLOGINFORMATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EVALUATIONRECOMMENDATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EVALUATIONREPORTREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ILMREVIEWFEEDBACK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ILMREVIEWREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MEDICALRECORDSCODINGPROCEDURE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MONTHLYCASEVOLUMEOTHERINDUSTRYDEDICATED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MONTHLYCASEVOLUMEOTHERINDUSTRYTOTAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MONTHLYCASEVOLUMEOTHERINSURERDEDICATED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MONTHLYCASEVOLUMEOTHERINSURERTOTAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PROACTIVEDECISIONMAKINGSCORE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PROVIDERGRADE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PROVIDERQUALIFIER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.QRSEVALUATIONDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.QRSSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.QRSTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.QUALITYCHECKSTAFFCOUNTDEDICATED AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.QUALITYCHECKSTAFFCOUNTTOTAL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REGIONALCOORDINATORREMARK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REGULARMEDICALAUDITINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REPAIRERCONDUCTFEEDBACK AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SITEVISITCONDUCTEDBY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SITEVISITCONDUCTEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SITEVISITDATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PROVIDER_QUALITY', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 100. MAXIMUS — SAT_AUG_PROVIDER_TARIFF   [Implemented]
-- HASHDIFF column HASHDIFF_AUG_PROVIDER_TARIFF. Recomputed exactly as automate_dv 0.11.5
-- / sat_multi_source computes it, from the payload stored on the same row. A match
-- proves every payload change changes the HASHDIFF, which is what drives a new row.
-- augmented satellite, automate_dv.sat; PK PARTY_HKEY; 1 RECORD_SOURCE group(s):
-- MAXIMUS_pd_prop_sp_pv [17 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_PROVIDER_TARIFF' as satellite, 'MAXIMUS_pd_prop_sp_pv' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF_AUG_PROVIDER_TARIFF is null) as null_hashdiff,
       count_if(HASHDIFF_AUG_PROVIDER_TARIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISCOUNTANDLOADINGTERMS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISCOUNTTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FLATRATEBASISINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(HOSPITALSPECIFICBILLITEMCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONSTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PACKAGEACCEPTANCEDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PACKAGETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STEPDOWNAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SURCHARGEPERCENTAGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFDOCUMENTREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFDOCUMENTSAVAILABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFLINEREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFMASTERUPLOADEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFSTANDARDISEDINDICATOR AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF_AUG_PROVIDER_TARIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISCOUNTANDLOADINGTERMS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DISCOUNTTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FLATRATEBASISINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(HOSPITALSPECIFICBILLITEMCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NEGOTIATIONSTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PACKAGEACCEPTANCEDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PACKAGETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STEPDOWNAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SURCHARGEPERCENTAGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFDOCUMENTREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFDOCUMENTSAVAILABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFLINEREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFMASTERUPLOADEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(TARIFFSTANDARDISEDINDICATOR AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF
 where (RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_PROVIDER_TARIFF' and record_source = 'MAXIMUS_pd_prop_sp_pv'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_maximus__pd_prop_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || ((nullif(trim(to_varchar("BAGIC_EMPLOYEE_CODE")), ''))) AS VARCHAR))), '')) as hkey,
               ("REC_REFRESH_AT"::timestamp_ntz) as ldts,
               to_varchar((nullif(trim(to_varchar("DELAYED_SUBMISSION_DISCOUNT_APPLICABLE")), ''))) as DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("DISCOUNT_AND_LOADING")), ''))) as DISCOUNTANDLOADINGTERMS,
               to_varchar((nullif(trim(to_varchar("DISCOUNT_TYPE")), ''))) as DISCOUNTTYPE,
               to_varchar((nullif(trim(to_varchar("FLAT_RATE_BASIS")), ''))) as FLATRATEBASISINDICATOR,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_SPECIIFIC_ITEM_CODES_IN_BILL")), ''))) as HOSPITALSPECIFICBILLITEMCODE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_END_DATE")), ''))) as NEGOTIATIONENDDATE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_REMARKS")), ''))) as NEGOTIATIONREMARKS,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_UNDER_NEGOTIATION_START_DATE")), ''))) as NEGOTIATIONSTARTDATE,
               to_varchar((nullif(trim(to_varchar("PACKAGE_ACCEPTANCE_DATE")), ''))) as PACKAGEACCEPTANCEDATE,
               to_varchar((nullif(trim(to_varchar("PACKAGE_TYPE")), ''))) as PACKAGETYPE,
               to_varchar((nullif(trim(to_varchar("STEP_DOWN_APPLICABLE")), ''))) as STEPDOWNAPPLICABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("SURCHARGE")), ''))) as SURCHARGEPERCENTAGE,
               to_varchar((nullif(trim(to_varchar("HOSPITAL_TARIFF_DOCS")), ''))) as TARIFFDOCUMENTREFERENCE,
               to_varchar((nullif(trim(to_varchar("VIEW_TARIFF_DOCS")), ''))) as TARIFFDOCUMENTSAVAILABLEINDICATOR,
               to_varchar((nullif(trim(to_varchar("STEP_DOWN_OPTION_FOR_ROOM_RENT_REMARKS")), ''))) as TARIFFLINEREMARKS,
               to_varchar((nullif(trim(to_varchar("TARIFF_MASTER_UPLOAD")), ''))) as TARIFFMASTERUPLOADEDINDICATOR,
               to_varchar((nullif(trim(to_varchar("TARIFF_STANDARDIZATION")), ''))) as TARIFFSTANDARDISEDINDICATOR
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.BUSINESS_PARTNERS_VW_DATA_PARTY_DETAIL_PARTY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_PROVIDER_TARIFF
     where RECORD_SOURCE = 'MAXIMUS_pd_prop_sp_pv' and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.DELAYEDSUBMISSIONDISCOUNTAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DISCOUNTANDLOADINGTERMS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DISCOUNTTYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.FLATRATEBASISINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.HOSPITALSPECIFICBILLITEMCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NEGOTIATIONENDDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NEGOTIATIONREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NEGOTIATIONSTARTDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PACKAGEACCEPTANCEDATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PACKAGETYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.STEPDOWNAPPLICABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SURCHARGEPERCENTAGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TARIFFDOCUMENTREFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TARIFFDOCUMENTSAVAILABLEINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TARIFFLINEREMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TARIFFMASTERUPLOADEDINDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TARIFFSTANDARDISEDINDICATOR AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_PROVIDER_TARIFF', 'MAXIMUS_pd_prop_sp_pv',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 101. MAXIMUS — CDC result (all satellites)   [Implemented]
-- Joins the BEFORE and AFTER captures of the same run id. raw_changed compares the
-- normalised RAW payload hash (same UPPER/TRIM/NULL rules as the HASHDIFF, so a
-- case-only RAW edit is not a change); new_rows = satellite rows added for the key
-- between the captures.
----------------------------------------------------------------------------------------
with b as (select * from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'BEFORE' and project = 'MAXIMUS'),
     a as (select * from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'AFTER'  and project = 'MAXIMUS'),
     k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1) as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)', iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), satellite, record_source;
